mutations.before:
try {
  await io.writeArtifact(path, serializeArtifact(artifact));
} catch (err: unknown) {
  io.log(`WARN: could not write artifact ${path}: ${errorText(err)}`);
}

mutations.after:
try {
  await io.writeArtifact(path, serializeArtifact(artifact));
} catch (err: unknown) {
  io.log(`WARN: could not write artifact ${path}: ${errorText(err)}`);
  return 1;
}

mutations.before:
if (backlog.state === "absent") {
  return ["backlog: no plan:verify run recorded"];
}

if (!backlog || backlog.state === "absent") {
  provEl.innerHTML = "";
  bodyEl.innerHTML = '<div class="backlog-empty">no plan:verify run recorded</div>';
  return;
}

mutations.after:
if (!backlog || backlog.state === "absent") {
  provEl.innerHTML = "";
  bodyEl.innerHTML = '<ul class="backlog-list"></ul>';
  return;
}

mutations.before:
if (err !== null && typeof err === "object" && "code" in err && (err as { code: unknown }).code === "ENOENT") {
  return { state: "absent" };
}
return { state: "unknown" };
